        if not isinstance(new_name, str) or new_name == "" or len(new_name) > 100:
            raise ValueError("Invalid name provided")
        self.name = new_name

    def changeAge(self, new_age):
        if not isinstance(new_age, int) or new_age < 0 or new_age > 150:
            raise ValueError("Invalid age provided")
        self.age = new_age

    def countHobbies(self):
        return len(self.hobbies)

    def printHobbies(self):
        if len(self.hobbies) == 0:
            print("No hobbies found")
        else:
            for hobby in self.hobbies:
                print(hobby)

    def getHobbies(self):
        return self.hobbies.copy()

    def hasHobby(self, hobby):
        return hobby in self.hobbies

    def getRandomHobby(self):
        if len(self.hobbies) == 0:
            return None
        return random.choice(self.hobbies)

