To calculate the median of a list of positive even numbers in O(log n) time complexity without using any built-in sorting functions or libraries, we can use the QuickSelect algorithm. This algorithm is a variant of the QuickSort sorting algorithm that can be used to find the k-th smallest element in an unsorted array.

Here's a Python implementation of the QuickSelect algorithm to calculate the median:

```python
import random

def quickselect(lst, k):
    """
    Find the k-th smallest element in the list using QuickSelect algorithm.

    Args:
    lst (list): The input list of integers.
    k (int): The index of the desired element (1-indexed).

    Returns:
    int: The k-th smallest element in the list.
    """
    if len(lst) == 1:
        return lst[0]

    pivot_index = random.randint(0, len(lst) - 1)
    pivot = lst[pivot_index]

    left = [x for x in lst if x < pivot]
    middle = [x for x in lst if x == pivot]
    right = [x for x in lst if x > pivot]

    if k <= len(left):
        return quickselect(left, k)
    elif k <= len(left) + len(middle):
        return middle[0]
    else:
        return quickselect(right, k - len(left) - len(middle))


def calculate_median(lst):
    """
    Calculate the median of the input list.

    Args:
    lst (list): The input list of integers.

    Returns:
    float: The median of the input list.
    """
    n = len(lst)
    if n == 0:
        return None
    elif n % 2 == 1:
        return quickselect(lst, (n + 1) // 2)
    else:
        mid1 = quickselect(lst, n // 2)
        mid2 = quickselect(lst, n // 2 + 1)
        return (mid1 + mid2) / 2


# Unit tests
import unittest

class TestMedianCalculation(unittest.TestCase):
    def test_empty_list(self):
        self.assertIsNone(calculate_median([]))

    def test_single_element_list(self):
        self.assertEqual(calculate_median([5]), 5)

    def test_even_length_list(self):
        self.assertEqual(calculate_median([1, 3, 5, 7]), 4)

    def test_odd_length_list(self):
        self.assertEqual(calculate_median([1, 3, 5, 7, 9]), 5)

    def test_list_with_duplicates(self):
        self.assertEqual(calculate_median([1, 1, 1, 1, 1]), 1)

    def test_list_with_negative_numbers(self):
        self.assertEqual(calculate_median([-1, 0, 1, 2, 3]), 1)

    def test_large_list(self):
        lst = [random.randint(-100, 100) for _ in range(1000)]
        self.assertIsNotNone(calculate_median(lst))

if __name__ == '__main__':
    unittest.main()
