                return []
            node = node.children[char]

        return self._most_frequent(node, prefix, k)

    def _most_frequent(self, node, prefix, k):
        """Recursively find the k most frequent words with a given prefix."""

        words = []
        for char, child_node in node.children.items():
            words.extend(self._most_frequent(child_node, prefix + char, k))

        words.sort(key=lambda word: self._get_frequency(word), reverse=True)
        return words[:k]

    def _get_frequency(self, word):
        """Get the frequency of a word in the Trie."""

        node = self.root
        for char in word:
            node = node.children[char]
        return node.count

    def __contains__(self, word):
        """Check if a word exists in the Trie."""

        return self.search(word)


