class TestTrie(unittest.TestCase):
    def test_insertion(self):
        trie = Trie()
        trie.insert("apple")
        trie.insert("banana")
        trie.insert("apple")
        self.assertTrue(trie.search("apple"))
        self.assertTrue(trie.search("banana"))

    def test_deletion(self):
        trie = Trie()
        trie.insert("apple")
        trie.insert("banana")
        trie.delete("apple")
        self.assertFalse(trie.search("apple"))
        with self.assertRaises(ValueError):
            trie.delete("apple")

    def test_search(self):
        trie = Trie()
        trie.insert("apple")
        trie.insert("banana")
        self.assertTrue(trie.search("apple"))
        self.assertTrue(trie.search("banana"))
        self.assertFalse(trie.search("orange"))

    def test_prefix_search(self):
        trie = Trie()
        trie.insert("apple")
        trie.insert("banana")
        trie.insert("orange")
        trie.insert("appetizer")
        self.assertEqual(trie.prefix_search("app"), ["apple", "appetizer"])
        self.assertEqual(trie.prefix_search("ban"), ["banana"])

    def test_most_frequent(self):
        trie = Trie()
        trie.insert("apple")
        trie.insert("banana")
        trie.insert("apple")
        trie.insert("banana")
        trie.insert("orange")
        self.assertEqual(trie.most_frequent("app", 1), ["apple"])
        self.assertEqual(trie.most_frequent("ban", 1), ["banana"])

