Below is a Python solution that encapsulates the prime and palindrome generation logic within a dedicated function. It includes error handling to manage cases where fewer than 10 palindromic primes can be generated within the specified range. Unit tests are also implemented to verify the correctness of the generated tuple.

```python
import random
import math

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_palindrome(n):
    """Check if a number is a palindrome."""
    return str(n) == str(n)[::-1]

def generate_palindrome_primes(start, end, count):
    """Generate a tuple of random prime numbers between start and end that are also palindromes."""
    palindrome_primes = []
    while len(palindrome_primes) < count:
        num = random.randint(start, end)
        if is_prime(num) and is_palindrome(num):
            palindrome_primes.append(num)
    return tuple(palindrome_primes)

def print_tuple(data, title):
    """Print a tuple with a clear title."""
    print(f"**{title}**")
    print(data)
    print(f"**{len(data)} elements**")

# Generate a tuple of 10 random prime numbers between 500 and 1000 that are also palindromes
try:
    palindrome_primes = generate_palindrome_primes(500, 1000, 10)
    print_tuple(palindrome_primes, "Palindrome Prime Tuple")
except ValueError as e:
    print(f"Error: {e}")

# Unit tests
import unittest

class TestPalindromePrimes(unittest.TestCase):
    def test_tuple_length(self):
        palindrome_primes = generate_palindrome_primes(500, 1000, 10)
        self.assertEqual(len(palindrome_primes), 10)

    def test_prime_and_palindrome(self):
        palindrome_primes = generate_palindrome_primes(500, 1000, 10)
        for num in palindrome_primes:
            self.assertTrue(is_prime(num))
            self.assertTrue(is_palindrome(num))

if __name__ == "__main__":
    unittest.main()
```

