            'email': contact['email'],
            'phone': contact['phone']
        },
        'hobbies': hobbies,
        'languages': languages,
        'education': {
            'degree': education['degree'],
            'major': education['major'],
            'university': education['university']
        },
        'experience': experience
    }

    return json.dumps(formatted_data)

# Example usage:
