            }
        }
    }
}

function mergeSort(myList, descending = false) {
    validateInput(myList);

    if (myList.length <= 1) {
        return myList;
    }

    const mid = Math.floor(myList.length / 2);
    const left = myList.slice(0, mid);
    const right = myList.slice(mid);

    return merge(mergeSort(left, descending), mergeSort(right, descending), descending);
}

function merge(left, right, descending) {
    const result = [];
    let i = 0;
    let j = 0;

    while (i < left.length && j < right.length) {
        if (descending) {
            if (left[i].age > right[j].age || (left[i].age === right[j].age && left[i].name > right[j].name)) {
