**Longest Palindromic Substring Algorithm**

The following algorithm uses a modified Manacher's algorithm to efficiently find the longest palindromic substring in a given character sequence. This approach ensures a time complexity of O(n) and a space complexity of O(n), where n is the length of the sequence.

### Code

```c
#include <stdio.h>
#include <stdlib.h>

// Structure to represent a node in the palindrome table
typedef struct Node {
    int length;
    int center;
} Node;

// Function to find the longest palindromic substring
char* longest_palindromic_substring(const char* sequence) {
    int n = 0;
    while (sequence[n] != '\0') {
        n++;
    }

    // Create a new string with a special character in the middle
    char* new_sequence = (char*)malloc((n * 2 + 3) * sizeof(char));
    new_sequence[0] = '#';
    int i = 0;
    while (sequence[i] != '\0') {
        new_sequence[n * 2 + 2] = '#';
        new_sequence[n * 2 + 1] = sequence[i];
        new_sequence[n * 2] = '#';
        i++;
    }
    new_sequence[n * 2 + 1] = '\0';

    // Initialize the palindrome table
    Node* palindrome_table = (Node*)malloc((n * 2 + 3) * sizeof(Node));
    int max_length = 0;
    int center = 0;

    // Iterate over the new sequence to fill the palindrome table
    for (int i = 0; i < n * 2 + 3; i++) {
        if (i == 0 || i == 1 || i == n * 2 + 1) {
            palindrome_table[i].length = 0;
            palindrome_table[i].center = 0;
        } else if (i <= center + 1) {
            palindrome_table[i].length = min(2 * (center - i + 1), palindrome_table[2 * center - i].length);
            palindrome_table[i].center = 2 * center - i;
        } else {
            int mirror = 2 * center - i;
            palindrome_table[i].length = 0;
            palindrome_table[i].center = 0;

            int l = 1;
            int r = palindrome_table[mirror].length;
            while (l + r < i && new_sequence[i - l - 1] == new_sequence[i + r + 1]) {
                palindrome_table[i].length = l + r + 1;
                l++;
                r++;
            }
            center = i;
        }

        if (palindrome_table[i].length > max_length) {
            max_length = palindrome_table[i].length;
            center = palindrome_table[i].center;
        }
    }

    // Find the longest palindromic substring
    int start = (center - max_length) / 2;
    int end = start + max_length - 1;
    char* longest_palindrome = (char*)malloc((max_length + 1) * sizeof(char));
    for (int i = 0; i < max_length; i++) {
        longest_palindrome[i] = sequence[start + i];
    }
    longest_palindrome[max_length] = '\0';

    // Clean up
    free(new_sequence);
    free(palindrome_table);

    return longest_palindrome;
}

int main() {
    const char* sequence = "babad";
    char* longest_palindrome = longest_palindromic_substring(sequence);
    printf("Longest palindromic substring: %s\n", longest_palindrome);
    free(longest_palindrome);
    return 0;
}
