def second_occurrence(nums, target):
    first_index = -1
    second_index = -1

    for i, num in enumerate(nums):
        if num == target:
            if first_index == -1:
                first_index = i
            else:
                second_index = i
                break

    if second_index == -1:
        return -1
    else:
        return second_index
```

