Here's a Python solution that uses a stack to keep track of the opening brackets and quotes. It iterates over the string, and whenever it encounters an opening bracket or quote, it pushes it onto the stack. When it encounters a closing bracket or quote, it pops the corresponding opening bracket or quote from the stack. If the stack is empty when it encounters a character, it counts it.

```python
def count_char_in_string(s, char):
    """
    Counts the occurrences of a character in a string, ignoring occurrences within parentheses, curly brackets, and quotes.

    Args:
        s (str): The input string.
        char (str): The character to count.

    Returns:
        int: The number of occurrences of the character in the string.
    """
    count = 0
    stack = []
    in_quote = False

    for i, c in enumerate(s):
        if c in ['(', '{', "'"]:
            stack.append(c)
            in_quote = False
        elif c in [')', '}']:
            stack.pop()
            if not stack:
                in_quote = False
        elif c == '"':
            in_quote = not in_quote
        elif not stack and not in_quote and c == char:
            count += 1

    return count


import unittest

class TestCountCharInString(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(count_char_in_string("", 'a'), 0)

    def test_string_with_only_quotes(self):
        self.assertEqual(count_char_in_string("'", 'a'), 0)

    def test_string_with_only_brackets(self):
        self.assertEqual(count_char_in_string("({})[]", 'a'), 0)

    def test_string_with_char(self):
        self.assertEqual(count_char_in_string("hello(how{are}you) 'hello'", 'o'), 2)

    def test_string_with_multiple_chars(self):
        self.assertEqual(count_char_in_string("hello(how{are}you) 'hello'", 'l'), 3)

    def test_string_with_no_char(self):
        self.assertEqual(count_char_in_string("hello(how{are}you) 'hello'", 'x'), 0)

    def test_string_with_nested_brackets(self):
        self.assertEqual(count_char_in_string("hello(how{are}you) 'hello(how{are}you)", 'o'), 2)

    def test_string_with_nested_quotes(self):
        self.assertEqual(count_char_in_string("hello 'hello 'hello'", 'o'), 3)

if __name__ == '__main__':
    unittest.main()
