```python
import unittest

def find_common_elements(*arrays):
    """
    Compare the elements of multiple arrays and print the elements that are present in all the arrays.
    Also, indicate the number of arrays each common element appears in.

    Args:
        *arrays: Variable number of arrays to compare.

    Returns:
        A dictionary where keys are common elements and values are the number of arrays each element appears in.
    """
    # Validate input arrays
    for i, array in enumerate(arrays):
        if not isinstance(array, list):
            raise ValueError(f"Array {i+1} is not a list")
        if not all(isinstance(x, int) for x in array):
            raise ValueError(f"Array {i+1} contains non-integer values")

    # Find common elements and their counts
    common_elements = {}
    for array in arrays:
        element_counts = {}
        for element in array:
            element_counts[element] = element_counts.get(element, 0) + 1
        for element, count in element_counts.items():
            common_elements[element] = common_elements.get(element, 0) + 1

    # Filter out elements that appear in fewer than all arrays
    common_elements = {element: count for element, count in common_elements.items() if count == len(arrays)}

    return common_elements


class TestFindCommonElements(unittest.TestCase):
    def test_common_elements(self):
        # Test case with common elements
        arrays = [[1, 2, 3], [2, 3, 4], [3, 4, 5]]
        self.assertEqual(find_common_elements(*arrays), {3: 3})

    def test_no_common_elements(self):
        # Test case with no common elements
        arrays = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
        self.assertEqual(find_common_elements(*arrays), {})

    def test_empty_arrays(self):
        # Test case with empty arrays
        arrays = [[], [], []]
        self.assertEqual(find_common_elements(*arrays), {})

    def test_duplicate_elements(self):
        # Test case with duplicate elements
        arrays = [[1, 2, 2], [2, 2, 3], [2, 3, 3]]
        self.assertEqual(find_common_elements(*arrays), {2: 3})

    def test_fewer_than_ten_arrays(self):
        # Test case with fewer than ten arrays
        arrays = [[1, 2, 3], [2, 3, 4]]
        self.assertEqual(find_common_elements(*arrays), {})

    def test_non_integer_values(self):
        # Test case with non-integer values
        with self.assertRaises(ValueError):
            find_common_elements([1, 2, '3'], [2, 3, 4])

    def test_non_list_values(self):
        # Test case with non-list values
        with self.assertRaises(ValueError):
            find_common_elements(1, 2, 3, [2, 3, 4])

if __name__ == '__main__':
    unittest.main()
```

