Here's a Python solution using the `json` module to parse the JSON data and a recursive function to clean the data.

```python
import json

def clean_json_data(data):
    """
    Recursively clean the JSON data by converting all fields to the same data type
    and handling nested objects and arrays of arbitrary depth.

    Args:
        data (dict or list): The JSON data to be cleaned.

    Returns:
        dict or list: The cleaned JSON data.
    """
    if isinstance(data, dict):
        # If the data is a dictionary, iterate over its items
        cleaned_data = {}
        for key, value in data.items():
            # If the value is a dictionary or a list, recursively clean it
            if isinstance(value, (dict, list)):
                cleaned_data[key] = clean_json_data(value)
            # If the value is a string, convert it to lowercase
            elif isinstance(value, str):
                cleaned_data[key] = value.lower()
            # If the value is an integer, convert it to a string
            elif isinstance(value, int):
                cleaned_data[key] = str(value)
            # If the value is a float, convert it to a string
            elif isinstance(value, float):
                cleaned_data[key] = str(value)
            # If the value is None, replace it with an empty string
            elif value is None:
                cleaned_data[key] = ""
            # If the value is of any other type, keep it as is
            else:
                cleaned_data[key] = value
        return cleaned_data
    elif isinstance(data, list):
        # If the data is a list, iterate over its elements
        cleaned_data = []
        for item in data:
            # If the item is a dictionary or a list, recursively clean it
            if isinstance(item, (dict, list)):
                cleaned_data.append(clean_json_data(item))
            # If the item is a string, convert it to lowercase
            elif isinstance(item, str):
                cleaned_data.append(item.lower())
            # If the item is an integer, convert it to a string
            elif isinstance(item, int):
                cleaned_data.append(str(item))
            # If the item is a float, convert it to a string
            elif isinstance(item, float):
                cleaned_data.append(str(item))
            # If the item is None, replace it with an empty string
            elif item is None:
                cleaned_data.append("")
            # If the item is of any other type, keep it as is
            else:
                cleaned_data.append(item)
        return cleaned_data
    else:
        # If the data is neither a dictionary nor a list, return it as is
        return data

# Example usage:
json_data = '''
{
    "name": {
        "firstname": "John",
        "lastname": "Doe"
    },
    "age": 30,
    "hobbies": ["reading", "writing", null, {
        "hobby": "coding"
    }],
    "address": {
        "street": "123 Main St",
        "city": "Anytown",
        "state": "CA",
        "zip": "12345"
    }
}
'''

# Load the JSON data
data = json.loads(json_data)

# Clean the JSON data
cleaned_data = clean_json_data(data)

# Print the cleaned JSON data
print(json.dumps(cleaned_data, indent=4))
