import re
from datetime import datetime

class Person:
    def __init__(self, name, age, address, hobbies=None):
        self.name = name
        self.age = age
        self.address = address
        self.hobbies = hobbies if hobbies else []
        self.addresses = []
        self.max_hobbies = 10
        self.max_addresses = 5

    def validate_age(self, age):
        if not isinstance(age, int) or age <= 0:
            raise ValueError("Age must be a positive integer")

    def validate_zip_code(self, zip_code):
        if not isinstance(zip_code, int) or len(str(zip_code)) != 5 or not str(zip_code).isdigit():
            raise ValueError("Zip code must be a 5-digit number")

    def validate_street_name(self, street_name):
        if not isinstance(street_name, str) or len(street_name) > 50 or not re.match("^[a-zA-Z ]+$", street_name):
            raise ValueError("Street name must be a string with a maximum of 50 characters and only contain letters and spaces")

    def validate_house_number(self, house_number):
        if not isinstance(house_number, int) or len(str(house_number)) > 10 or not str(house_number).isdigit():
            raise ValueError("House number must be a positive integer with a maximum of 10 digits")

    def validate_city(self, city):
        if not isinstance(city, str) or len(city) > 50 or not re.match("^[a-zA-Z ]+$", city):
            raise ValueError("City must be a string with a maximum of 50 characters and only contain letters and spaces")

    def validate_state(self, state):
        if not isinstance(state, str) or len(state) > 50 or not re.match("^[a-zA-Z ]+$", state):
            raise ValueError("State must be a string with a maximum of 50 characters and only contain letters and spaces")

    def validate_hobbies(self, hobbies):
        if not isinstance(hobbies, list) or not all(isinstance(hobby, str) for hobby in hobbies):
            raise ValueError("Hobbies must be a list of strings")

    def validate_full_address(self, full_address):
        if not isinstance(full_address, str) or len(full_address) > 200 or not re.match("^[a-zA-Z0-9\s.,-]+$", full_address):
            raise ValueError("Full address must be a string with a maximum of 200 characters and only contain letters, numbers, spaces, periods, commas, and hyphens")

    def validate_birth_year(self, birth_year):
        if not isinstance(birth_year, int) or len(str(birth_year)) != 4 or not str(birth_year).isdigit():
            raise ValueError("Birth year must be a 4-digit number")

    def validate_location(self, location):
        if not isinstance(location, str) or len(location) > 50 or not re.match("^[a-zA-Z ]+$", location):
            raise ValueError("Location must be a string with a maximum of 50 characters and only contain letters and spaces")

    def add_hobby(self, hobby):
        if len(self.hobbies) < self.max_hobbies:
            self.hobbies.append(hobby)
        else:
            raise ValueError("Maximum number of hobbies reached")

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)
        else:
            raise ValueError("Hobby not found")

    def search_hobby(self, hobby):
        return hobby.lower() in [h.lower() for h in self.hobbies]

    def add_address(self, address):
        if len(self.addresses) < self.max_addresses:
            self.addresses.append(address)
        else:
            raise ValueError("Maximum number of addresses reached")

    def remove_address(self, address_id):
        if address_id < len(self.addresses):
            del self.addresses[address_id]
        else:
            raise ValueError("Address not found")

    def get_address(self, address_id):
        if address_id < len(self.addresses):
            return self.addresses[address_id]
        else:
            raise ValueError("Address not found")

    def calculate_age_in_months(self):
        self.validate_age(self.age)
        birth_date = datetime.now() - datetime.timedelta(days=self.age*365)
        return (datetime.now().year - birth_date.year) * 12 + (datetime.now().month - birth_date.month)

    def calculate_birth_year(self):
        self.validate_age(self.age)
        return datetime.now().year - self.age

    def calculate_full_address(self):
        self.validate_full_address(self.address.street_name + " " + str(self.address.house_number) + ", " + self.address.city + ", " + self.address.state + " " + str(self.address.zip_code))
        return self.address.street_name + " " + str(self.address.house_number) + ", " + self.address.city + ", " + self.address.state + " " + str(self.address.zip_code)

    def display_data(self):
        print(f"Name: {self.name}")
        print(f"Age: {self.age} years")
        print(f"Age in months: {self.calculate_age_in_months()} months")
        print(f"Birth year: {self.calculate_birth_year()}")
        print(f"Address: {self.calculate_full_address()}")
        print(f"Hobbies: {', '.join(self.hobbies)}")
        print(f"Addresses: {[f'{i+1}. {address}' for i, address in enumerate(self.addresses)]}")

class Address:
