```python
def count_occurrences(data, item):
    """
    Count the occurrences of an item in a given list or dictionary, 
    including nested lists and dictionaries.

    Args:
        data (list or dict): The input data to search in.
        item: The item to search for.

    Returns:
        int: The count of occurrences of the item.

    Raises:
        TypeError: If the input data is not a list or dictionary.
    """

    # Check if the input data is a list or dictionary
    if not isinstance(data, (list, dict)):
        raise TypeError("Input data must be a list or dictionary")

    # Initialize the count to 0
    count = 0

    # If the data is a list, iterate over its elements
    if isinstance(data, list):
        for element in data:
            # If the element is a list or dictionary, recursively count its occurrences
            if isinstance(element, (list, dict)):
                count += count_occurrences(element, item)
            # If the element is the item, increment the count
            elif element == item:
                count += 1

    # If the data is a dictionary, iterate over its values
    elif isinstance(data, dict):
        for value in data.values():
            # If the value is a list or dictionary, recursively count its occurrences
            if isinstance(value, (list, dict)):
                count += count_occurrences(value, item)
            # If the value is the item, increment the count
            elif value == item:
                count += 1

    # Return the count
    return count


