class HTMLParser:
    def __init__(self):
        self.stack = []
        self.text = ""

    def parse(self, html):
        i = 0
        while i < len(html):
            if html[i] == '<':
                if html[i+1] != '/':
                    self.stack.append(html[i+1:html.find('>', i)])
                    i = html.find('>', i) + 1
                else:
                    tag = html[i+2:html.find('>', i)]
                    if self.stack and self.stack[-1] == tag:
                        self.stack.pop()
                    i = html.find('>', i) + 1
            else:
                self.text += html[i]
                i += 1

    def extract_text(self, tag):
        if not self.stack:
            return ""
        if not self.text:
            return ""
        if tag not in self.stack:
            return ""
        result = ""
        while self.stack and self.stack[-1] == tag:
            result = self.text[:self.text.find('<', self.text.find(self.stack[-1]) + len(self.stack[-1]))] + result
            self.text = self.text[self.text.find('<', self.text.find(self.stack[-1]) + len(self.stack[-1])) + 1:]
            self.stack.pop()
        return result


# Unit tests
import unittest

class TestHTMLParser(unittest.TestCase):
    def test_example1(self):
        parser = HTMLParser()
        parser.parse("<div class='header'>Hello!</div>")
        self.assertEqual(parser.extract_text("div"), "Hello!")

    def test_example2(self):
        parser = HTMLParser()
        parser.parse("<div class='header'><span>Welcome</span><span>to</span><span>the</span><span>world</span></div>")
        self.assertEqual(parser.extract_text("span"), "Welcome to the world")

