        parser.parse("")
        self.assertEqual(parser.extract_text("div"), "")

    def test_no_tag(self):
        parser = HTMLParser()
        parser.parse("<div class='header'>Hello!</div>")
        self.assertEqual(parser.extract_text("span"), "")

    def test_nested_tags(self):
