```python
from datetime import datetime
from abc import ABC, abstractmethod
from enum import Enum
from dataclasses import dataclass

# Define an enumeration for species
class Species(Enum):
    MAMMAL = 1
    BIRD = 2
    FISH = 3

# Define a dataclass for food
@dataclass
class Food:
    name: str
    nutritional_value: float
    species: Species

# Define a parent class for living beings
class LivingBeing:
    def __init__(self, name, species):
        self.name = name
        self.species = species
        self.creation_date = datetime.now()

    @property
    def age(self):
        return (datetime.now() - self.creation_date).days / 365

# Define a method to calculate average lifespan based on species
def get_average_lifespan(species):
    if species == Species.MAMMAL:
        return 15
    elif species == Species.BIRD:
        return 5
    elif species == Species.FISH:
        return 3
    else:
        raise ValueError("Invalid species")

# Define the Animal class
class Animal(LivingBeing):
    def __init__(self, name, species, average_lifespan):
        super().__init__(name, species)
        self.average_lifespan = average_lifespan
        self.age = (datetime.now() - self.creation_date).days / self.average_lifespan

    @property
    def age(self):
        return (datetime.now() - self.creation_date).days / self.average_lifespan

    def eat(self, food):
        if food.species != self.species:
            raise ValueError("Invalid food for species")
        self.age += food.nutritional_value / 1000  # Update age based on nutritional value
        print(f"{self.name} ate {food.name}")

    @staticmethod
    def compare_age(animal1, animal2):
        return animal1.age > animal2.age

    @staticmethod
    def get_average_lifespan(species):
        return get_average_lifespan(species)

    def speak(self):
        if self.species == Species.MAMMAL:
            print("Mooooo")
        elif self.species == Species.BIRD:
            print("Chirp")
        elif self.species == Species.FISH:
            print("Glub glub")

    def move(self):
        if self.species == Species.MAMMAL:
            print("Walking")
        elif self.species == Species.BIRD:
            print("Flying")
        elif self.species == Species.FISH:
            print("Swimming")

    def reproduce(self):
        return Animal(self.name + " Jr.", self.species, self.average_lifespan)

# Define a subclass for mammals
class Mammal(Animal):
    def __init__(self, name, species, average_lifespan, fur_color):
        super().__init__(name, species, average_lifespan)
        self.fur_color = fur_color

    def milk(self):
        print(f"{self.name} is producing milk")

    def speak(self):
        print("Mooooo")

    def move(self):
        print("Walking")

# Define a subclass for birds
class Bird(Animal):
    def __init__(self, name, species, average_lifespan, wing_span):
        super().__init__(name, species, average_lifespan)
        self.wing_span = wing_span

    def fly(self):
        print(f"{self.name} is flying with a wing span of {self.wing_span} inches")

    def speak(self):
        print("Chirp")

    def move(self):
        print("Flying")

# Define a subclass for fish
class Fish(Animal):
    def __init__(self, name, species, average_lifespan, water_type):
        super().__init__(name, species, average_lifespan)
        self.water_type = water_type

    def swim(self):
        print(f"{self.name} is swimming in {self.water_type} water")

    def speak(self):
        print("Glub glub")

    def move(self):
        print("Swimming")

# Example usage:
mammal = Mammal("Bessie", Species.MAMMAL, 15, "Brown")
mammal.eat(Food("Grass", 100, Species.MAMMAL))
mammal.speak()
mammal.move()
mammal.milk()

bird = Bird("Tweety", Species.BIRD, 5, 10)
bird.eat(Food("Seeds", 50, Species.BIRD))
bird.speak()
bird.move()
bird.fly()

fish = Fish("Goldie", Species.FISH, 3, "Freshwater")
fish.eat(Food("Fish food", 200, Species.FISH))
fish.speak()
fish.move()
fish.swim()

print(Animal.compare_age(mammal, bird))
print(Animal.get_average_lifespan(Species.MAMMAL))
