To solve this problem, we can use dynamic programming. We will create two 2D arrays, `dp` and `sum_dp`, where `dp[i][j]` is `True` if there exists a subsequence of the first `i` numbers that sums up to `j`, and `sum_dp[i][j]` is the maximum length of such a subsequence.

Here is a Python solution:

```python
def longest_increasing_subsequence_with_sum(arr, target_sum):
    n = len(arr)
    dp = [[False] * (target_sum + 1) for _ in range(n)]
    sum_dp = [[0] * (target_sum + 1) for _ in range(n)]

    # Initialize the first row
    for j in range(target_sum + 1):
        if arr[0] <= j:
            dp[0][j] = True
            sum_dp[0][j] = 1
        else:
            dp[0][j] = False
            sum_dp[0][j] = 0

    # Fill up the dp and sum_dp arrays
    for i in range(1, n):
        for j in range(1, target_sum + 1):
            if arr[i] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i]]
                if dp[i][j]:
                    sum_dp[i][j] = max(sum_dp[i-1][j], sum_dp[i-1][j-arr[i]] + 1)
                else:
                    sum_dp[i][j] = sum_dp[i-1][j]
            else:
                dp[i][j] = dp[i-1][j]
                sum_dp[i][j] = sum_dp[i-1][j]

    # Find the maximum length of a subsequence with sum greater than the target sum
    max_length = 0
    for i in range(n):
        for j in range(target_sum + 1):
            if dp[i][j] and j > target_sum / 2:
                max_length = max(max_length, sum_dp[i][j])

    # Find the subsequence with the maximum length
    subsequence = []
    i, j = n - 1, target_sum
    while i >= 0 and j >= 0:
        if dp[i][j]:
            if sum_dp[i][j] > max_length:
                max_length = sum_dp[i][j]
                subsequence = [arr[i]]
            if j >= arr[i] and dp[i-1][j-arr[i]]:
                subsequence.insert(0, arr[i-1])
                j -= arr[i]
                i -= 1
            else:
                i -= 1
        else:
            i -= 1

    return max_length, subsequence

arr = [10,22,9,33,21,50,41,60]
