                "C": [9, 7, 3, 1, 8, 6, 2, 1],
            }
        )
        transformed_df, fig = task_func(df)
        self.assertEqual(transformed_df.shape, df.shape)
    def test_case_2(self):
        df = pd.DataFrame({"A": [1, 1, 1], "B": [3, 3, 3], "C": [4, 4, 4]})
        transformed_df, fig = task_func(df)
        self.assertEqual(transformed_df.shape, df.shape)
        self.assertEqual(len(fig.axes[0].lines), 0)
