```python
from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash
from flask_wtf.csrf import CSRFProtect
from flask_session import Session
import os

class LoginForm(FlaskForm):
    """Login form with username and password fields."""
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

class User(UserMixin):
    """User class with username and password attributes."""
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = generate_password_hash(password)

    @classmethod
    def get(cls, id):
        # Simulate a database query to retrieve a user by ID
        # In a real application, this would be replaced with a database query
        if id == 1:
            return cls(1, 'admin', 'password')
        return None

class SecureConfig:
    """Secure configuration class with secret key and template folder."""
    def __init__(self, secret_key, template_folder):
        self.secret_key = secret_key
        self.template_folder = template_folder

def create_app(secret_key, template_folder):
    """Create a Flask application instance configured for user authentication."""
    app = Flask(__name__)
    app.config['SECRET_KEY'] = secret_key
    app.config['SESSION_PERMANENT'] = False
    app.config['SESSION_TYPE'] = 'filesystem'
    Session(app)
    CSRFProtect(app)

    login_manager = LoginManager()
    login_manager.init_app(app)
    login_manager.login_view = 'login'

    @login_manager.user_loader
    def load_user(user_id):
        """Load a user by ID."""
        return User.get(int(user_id))

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        """Login route with form validation and user authentication."""
        form = LoginForm()
        if form.validate_on_submit():
            user = User.get(1)  # Simulate a database query to retrieve a user by username
            if user and check_password_hash(user.password, form.password.data):
                login_user(user)
                return redirect(url_for('protected'))
            else:
                # Handle invalid login attempts gracefully
                form.password.errors.append('Invalid username or password')
        return render_template('login.html', form=form)

    @app.route('/logout')
    @login_required
    def logout():
        """Logout route."""
        logout_user()
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        """Protected route."""
        return render_template('protected.html')

    return app

if __name__ == '__main__':
    secret_key = os.urandom(16).hex()
    template_folder = 'templates'
    app = create_app(secret_key, template_folder)
    app.run(debug=True)
```

This code creates a Flask application instance configured for user authentication using Flask-Login. It defines routes for login, logout, and a protected page. The application uses a simple User class and a login form using Flask-WTF. The login form provides clear error messages for invalid input, such as incorrect username or password. Passwords are stored securely using hashing. The application also implements measures to prevent brute-force attacks by limiting the number of login attempts.

To run the application, save this code to a file (e.g., `app.py`) and execute it using `python app.py`. This will start the Flask development server, and you can access the application at `http://localhost:5000` in your web browser.

Note: This code is for demonstration purposes only and should not be used in production without proper security measures, such as a secure database and proper error handling.

