import re

class Runtime:
    def __init__(self):
        self.variables = {}
        self.functions = {}
        self.builtins = {
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'asin': math.asin,
            'acos': math.acos,
