        }

    def execute(self, statement):
        if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*\s*=\s*.*$', statement):
            self.assign_variable(statement)
        elif re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*\s*:\s*.*$', statement):
            self.define_function(statement)
        elif re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*\s*\(\s*.*\s*\)$', statement):
            self.call_function(statement)
        else:
            try:
                result = self.evaluate_expression(statement)
                print(f"Result: {result}")
            except Exception as e:
                print(f"Error: {e}")

    def assign_variable(self, statement):
        match = re.match(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*(.*)', statement)
        if match:
            var_name = match.group(1)
            value = self.evaluate_expression(match.group(2))
            self.variables[var_name] = value
            print(f"Variable '{var_name}' assigned to {value}")
        else:
            print("Invalid variable assignment")

    def define_function(self, statement):
        match = re.match(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*:\s*(.*)', statement)
        if match:
            func_name = match.group(1)
            func_body = match.group(2)
            self.functions[func_name] = func_body
            print(f"Function '{func_name}' defined")
        else:
            print("Invalid function definition")

    def call_function(self, statement):
        match = re.match(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*\((.*)\)', statement)
        if match:
            func_name = match.group(1)
            args = match.group(2)
            if func_name in self.functions:
                func_body = self.functions[func_name]
                result = self.evaluate_expression(func_body, args.split(','))
                print(f"Result of function '{func_name}': {result}")
            elif func_name in self.builtins:
                args = [self.evaluate_expression(arg) for arg in args.split(',')]
                result = self.builtins[func_name](*args)
                print(f"Result of function '{func_name}': {result}")
            else:
                print(f"Undefined function '{func_name}'")
        else:
            print("Invalid function call")

    def evaluate_expression(self, expression, args=None):
        if args is None:
            args = []
        expression = expression.replace('(', '( ').replace(')', ' )')
        tokens = re.findall(r'\d+\.\d+|\d+|[a-zA-Z_][a-zA-Z0-9_]*|\+|-|\*|\/|\(|\)', expression)
        for i, token in enumerate(tokens):
            if token in self.variables:
                tokens[i] = str(self.variables[token])
            elif token in self.functions:
                tokens[i] = f"self.call_function('{token}({args[i]})')"
            elif token in self.builtins:
                tokens[i] = f"self.builtins['{token}']({args[i]})"
        expression = ' '.join(tokens)
        return eval(expression, {'self': self})

    def start_shell(self):
        while True:
            user_input = input(">>> ")
            if user_input == "exit()":
