```python
import turtle
import unittest

class Scoreboard(turtle.Turtle):
    def __init__(self):
        super().__init__()
        self.hideturtle()
        self.penup()
        self.goto(-200, 250)
        self.level = 1
        self.update_scoreboard()

    def update_scoreboard(self):
        self.clear()
        self.write(f"Level: {self.level}", align="left", font=("Arial", 24, "normal"))

    def increase_level(self):
        self.level += 1
        self.update_scoreboard()

    def game_over(self):
        self.clear()
        self.write("GAME OVER", align="center", font=("Arial", 36, "bold"))


class Game:
    def __init__(self):
        self.scoreboard = Scoreboard()
        self.screen = turtle.Screen()
        self.screen.setup(800, 600)
        self.screen.listen()
        self.screen.onkey(self.increase_level, "Up")
        self.screen.onkey(self.game_over, "space")

    def increase_level(self):
        self.scoreboard.increase_level()
        if self.scoreboard.level > 10:
            self.game_over()

    def game_over(self):
        self.scoreboard.game_over()
        self.screen.onkey(None, "Up")
        self.screen.onkey(None, "space")

    def run(self):
        self.screen.mainloop()


class TestScoreboard(unittest.TestCase):
    def setUp(self):
        self.scoreboard = Scoreboard()

    def test_initial_level(self):
        self.assertEqual(self.scoreboard.level, 1)

    def test_increase_level(self):
        self.scoreboard.increase_level()
        self.assertEqual(self.scoreboard.level, 2)

    def test_increase_level_multiple_times(self):
        for _ in range(10):
            self.scoreboard.increase_level()
        self.assertEqual(self.scoreboard.level, 11)

    def test_game_over(self):
        self.scoreboard.level = 10
        self.scoreboard.game_over()
        self.assertEqual(self.scoreboard.level, 10)


class TestGame(unittest.TestCase):
    def setUp(self):
        self.game = Game()

    def test_increase_level(self):
        self.game.screen.onkey(None, "Up")
        self.game.screen.onkey(None, "space")
        self.game.increase_level()
        self.assertEqual(self.game.scoreboard.level, 2)

    def test_game_over(self):
        self.game.screen.onkey(None, "Up")
        self.game.screen.onkey(None, "space")
        self.game.scoreboard.level = 10
        self.game.game_over()
        self.assertEqual(self.game.scoreboard.level, 10)


if __name__ == "__main__":
    unittest.main(exit=False)
    game = Game()
    game.run()
