        # Mock the S3 event
        event = {
            'Records': [
                {
                    's3': {
                        'bucket': {
                            'name': 'my-bucket'
                        },
                        'key': 'path/to/object.txt'
                    }
                }
            ]
        }

        # Mock the S3 client
        with patch('boto3.client') as mock_s3_client:
            mock_s3_client.return_value.get_object.return_value = {
                'Body': MagicMock(read=lambda: b'Hello, World!')
            }

            # Call the Lambda handler
            result = lambda_handler(event, None)

            # Assert the result
            self.assertEqual(result['s3_object_content'], 'Hello, World!')
            self.assertEqual(result['execution_details'], event)

    def test_invalid_s3_event(self):
