```python
import math
import random
import time
import unittest

class Graph:
    def __init__(self, num_nodes):
        self.num_nodes = num_nodes
        self.adj_matrix = [[0 for _ in range(num_nodes)] for _ in range(num_nodes)]
        self.node_coords = self.generate_node_coords()

    def generate_node_coords(self):
        node_coords = []
        for i in range(self.num_nodes):
            x = random.uniform(0, 10)
            y = random.uniform(0, 10)
            node_coords.append((x, y))
        return node_coords

    def calculate_distance(self, node1, node2):
        return math.sqrt((node1[0] - node2[0])**2 + (node1[1] - node2[1])**2)

    def construct_graph(self):
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                distance = self.calculate_distance(self.node_coords[i], self.node_coords[j])
                if distance <= 10:  # maximum diameter constraint
                    self.adj_matrix[i][j] = 1
                    self.adj_matrix[j][i] = 1

    def check_constraints(self):
        # check if graph is fully connected
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i][j] == 0:
                    return False

        # check if maximum diameter is 4
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i][j] == 1:
                    distance = self.calculate_distance(self.node_coords[i], self.node_coords[j])
                    if distance > 10:
                        return False

        # check if each node has degree 3
        for i in range(self.num_nodes):
            degree = sum(self.adj_matrix[i])
            if degree != 3:
                return False

        return True

    def calculate_total_cost(self):
        total_cost = 0
        for i in range(self.num_nodes):
            for j in range(i+1, self.num_nodes):
                if self.adj_matrix[i][j] == 1:
                    distance = self.calculate_distance(self.node_coords[i], self.node_coords[j])
                    total_cost += distance
        return total_cost

    def greedy_local_search(self):
        start_time = time.time()
        for _ in range(100):
            max_cost_edge = (-1, -1)
            max_cost = 0
            for i in range(self.num_nodes):
                for j in range(i+1, self.num_nodes):
                    if self.adj_matrix[i][j] == 1:
                        distance = self.calculate_distance(self.node_coords[i], self.node_coords[j])
                        if distance > max_cost:
                            max_cost = distance
                            max_cost_edge = (i, j)
            if max_cost_edge == (-1, -1):
                break
            self.adj_matrix[max_cost_edge[0]][max_cost_edge[1]] = 0
            self.adj_matrix[max_cost_edge[1]][max_cost_edge[0]] = 0
            if self.check_constraints():
                total_cost = self.calculate_total_cost()
                if total_cost < self.total_cost_before_optimization:
                    self.total_cost_before_optimization = total_cost
            else:
                self.adj_matrix[max_cost_edge[0]][max_cost_edge[1]] = 1
                self.adj_matrix[max_cost_edge[1]][max_cost_edge[0]] = 1
        end_time = time.time()
        self.runtime_greedy_local_search = end_time - start_time

    def original_heuristic_algorithm(self):
        start_time = time.time()
        self.total_cost_before_optimization = float('inf')
        while True:
            self.construct_graph()
            if self.check_constraints():
                total_cost = self.calculate_total_cost()
                if total_cost < self.total_cost_before_optimization:
                    self.total_cost_before_optimization = total_cost
                    self.total_cost_after_optimization = total_cost
                else:
                    break
            else:
                self.construct_graph()
        end_time = time.time()
        self.runtime_original_heuristic_algorithm = end_time - start_time

    def optimize_graph(self):
        self.total_cost_before_optimization = float('inf')
        self.greedy_local_search()
        self.original_heuristic_algorithm()

    def print_graph(self):
        print("Node Coordinates:")
        for i in range(self.num_nodes):
            print(f"Node {i+1}: ({self.node_coords[i][0]}, {self.node_coords[i][1]})")
        print("\nAdjacency Matrix:")
        for row in self.adj_matrix:
            print(row)
        print(f"\nTotal Cost Before Optimization: {self.total_cost_before_optimization}")
        print(f"Total Cost After Optimization: {self.total_cost_after_optimization}")
        print(f"Runtime Greedy Local Search: {self.runtime_greedy_local_search} seconds")
        print(f"Runtime Original Heuristic Algorithm: {self.runtime_original_heuristic_algorithm} seconds")

class TestGraph(unittest.TestCase):
    def test_graph_generation(self):
        graph = Graph(5)
        self.assertEqual(graph.num_nodes, 5)
        self.assertEqual(len(graph.adj_matrix), 5)
        self.assertEqual(len(graph.adj_matrix[0]), 5)
        self.assertEqual(len(graph.node_coords), 5)

    def test_check_constraints(self):
        graph = Graph(5)
        graph.construct_graph()
        self.assertTrue(graph.check_constraints())

    def test_calculate_total_cost(self):
        graph = Graph(5)
        graph.construct_graph()
        total_cost = graph.calculate_total_cost()
        self.assertGreaterEqual(total_cost, 0)

    def test_greedy_local_search(self):
        graph = Graph(5)
        graph.optimize_graph()
        self.assertLessEqual(graph.total_cost_after_optimization, graph.total_cost_before_optimization)

    def test_original_heuristic_algorithm(self):
        graph = Graph(5)
        graph.optimize_graph()
        self.assertLessEqual(graph.total_cost_after_optimization, graph.total_cost_before_optimization)

