In `core/forms.py`, create a form for searching wallpapers:

```python
from django import forms
from django.core.exceptions import ValidationError

class WallpaperForm(forms.Form):
    search_phrase = forms.CharField(max_length=255, required=False)
    random = forms.BooleanField(required=False)
```

In `core/views.py`, create a view function to handle form submission:

```python
import requests
import base64
from django.http import JsonResponse, HttpResponse
from django.shortcuts import render
from .forms import WallpaperForm
from .models import Wallpaper

def wallpaper(request):
    if request.method == 'POST':
        form = WallpaperForm(request.POST)
        if form.is_valid():
            search_phrase = form.cleaned_data['search_phrase']
            random = form.cleaned_data['random']
            try:
                images = convert_images(search_phrase, random)
                return JsonResponse({'images': images})
            except Exception as e:
                return JsonResponse({'error': str(e)})
    else:
        form = WallpaperForm()
    return render(request, 'home.html', {'form': form})
```

In `core/helpers.py`, create a helper function to fetch images from Wallhaven:

```python
import requests
import base64
from bs4 import BeautifulSoup

def convert_images(search_phrase, random):
    if random:
        url = 'https://wallhaven.cc/random'
    else:
        url = f'https://wallhaven.cc/search?q={search_phrase}'
    try:
        response = requests.get(url)
        soup = BeautifulSoup(response.text, 'html.parser')
        images = []
        for img in soup.find_all('img', class_='preview'):
            src = img.get('src')
            if src:
                response = requests.get(src)
                image_data = base64.b64encode(response.content).decode('utf-8')
                extension = src.split('.')[-1]
                images.append((extension, image_data))
        return images
    except Exception as e:
        raise Exception(f'Failed to fetch images: {str(e)}')
```

