import argparse
import logging
import os
import requests
from requests.auth import HTTPBasicAuth
from urllib.parse import urljoin

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def authenticate_jira(username, password, jira_url):
    """Authenticate with the Apache JIRA instance."""
    try:
        response = requests.get(urljoin(jira_url, 'rest/api/2/myself'), auth=HTTPBasicAuth(username, password))
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        logging.error(f"Authentication failed: {e}")
        raise

def fetch_issues(jira_url, fix_version, jql):
    """Fetch issues for a specified version that are resolved with a resolution of "Fixed" or "Done"."""
    try:
        response = requests.get(urljoin(jira_url, 'rest/api/2/search'), params={'jql': jql, 'fields': 'key,summary,resolution'}, auth=HTTPBasicAuth(os.environ['JIRA_USERNAME'], os.environ['JIRA_PASSWORD']))
        response.raise_for_status()
        return response.json()['issues']
    except requests.exceptions.RequestException as e:
        logging.error(f"Failed to fetch issues: {e}")
        raise

def group_issues(issues, is_website):
    """Group issues by type for markdown output or by category for website output."""
    if is_website:
        categories = {}
        for issue in issues:
            category = issue['fields']['customfield_12345']  # Replace with the actual category field ID
            if category not in categories:
                categories[category] = []
            categories[category].append(issue)
        return categories
    else:
        issue_types = {}
        for issue in issues:
            issue_type = issue['fields']['issuetype']['name']
            if issue_type not in issue_types:
                issue_types[issue_type] = []
            issue_types[issue_type].append(issue)
        return issue_types

def format_output(issues, is_website):
    """Format the output as markdown or website HTML."""
    if is_website:
        output = ''
        for category, category_issues in issues.items():
            output += f'<h2>{category}</h2>\n'
            for issue in category_issues:
                output += f'<p><a href="{issue["key"]}">{issue["key"]}</a> - {issue["fields"]["summary"]}</p>\n'
        return output
    else:
        output = ''
        for issue_type, issue_type_issues in issues.items():
            output += f'## {issue_type}\n\n'
            for issue in issue_type_issues:
                output += f'* [{issue["key"]}]({issue["key"]}) - {issue["fields"]["summary"]}\n'
        return output

def main():
    parser = argparse.ArgumentParser(description='Generate a changelog for a given version of the Apache Arrow project from its JIRA issues.')
    parser.add_argument('fix_version', help='The version of the project for which the changelog is being generated.')
    parser.add_argument('is_website', nargs='?', default='0', type=int, help='Indicates that the output should be formatted for the website (default: 0).')
    args = parser.parse_args()

    jira_url = 'https://issues.apache.org/jira'  # Replace with the actual JIRA instance URL
    jql = f'fixVersion = "{args.fix_version}" AND resolution = "Fixed" OR resolution = "Done"'
    is_website = args.is_website == 1

    try:
        username = os.environ['JIRA_USERNAME']
        password = os.environ['JIRA_PASSWORD']
        authenticate_jira(username, password, jira_url)
    except KeyError:
        logging.error('JIRA_USERNAME and JIRA_PASSWORD environment variables are not set.')
        return
    except Exception as e:
        logging.error(f"Authentication failed: {e}")
        return

    try:
        issues = fetch_issues(jira_url, args.fix_version, jql)
    except Exception as e:
        logging.error(f"Failed to fetch issues: {e}")
        return

    issues = group_issues(issues, is_website)
    output = format_output(issues, is_website)

    if is_website:
        print(output)
    else:
        print(output)

if __name__ == '__main__':
    main()
