```python
import dateutil.parser
from datetime import datetime, date
from typing import Union

class CongressError(Exception):
    """Custom exception class for general Congress API errors."""
    def __init__(self, message: str, response: dict = None, url: str = None):
        self.message = message
        self.response = response
        self.url = url
        super().__init__(message)

class NotFound(CongressError):
    """Subclass of CongressError for items not found in the API."""
    pass

def check_chamber(chamber: str) -> None:
    """Validate whether a given chamber is one of 'house', 'senate', or 'both'."""
    if chamber not in ['house', 'senate', 'both']:
        raise TypeError("Invalid chamber. Must be 'house', 'senate', or 'both'.")

def get_congress(year: int) -> int:
    """Calculate the Congress number based on a given year."""
    if year < 1789:
        raise CongressError("Year must be 1789 or later.")
    return (year - 1789) // 2 + 1

def parse_date(date_str: Union[str, datetime, date]) -> datetime:
    """Parse a date string into a datetime object."""
    if isinstance(date_str, (datetime, date)):
        return date_str
    try:
        return dateutil.parser.parse(date_str)
    except AttributeError:
        pass
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        raise CongressError("Invalid date format.")

def u(text: bytes) -> str:
    """Ensure a given text is returned as a Unicode string."""
    if isinstance(text, str):
        return text
    return text.decode('utf-8').replace('\r\n', '\n')

def get_offset(page: int) -> int:
    """Calculate the offset for pagination in the API."""
    if page < 1:
        raise CongressError("Page number must be 1 or greater.")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.now().year)

# Test cases
import unittest

class TestCongressUtils(unittest.TestCase):
    def test_check_chamber(self):
        check_chamber('house')
        check_chamber('senate')
        check_chamber('both')
        with self.assertRaises(TypeError):
            check_chamber('invalid')

    def test_get_congress(self):
        self.assertEqual(get_congress(1789), 1)
        self.assertEqual(get_congress(1790), 2)
        with self.assertRaises(CongressError):
            get_congress(1788)

    def test_parse_date(self):
        self.assertEqual(parse_date('2022-01-01'), datetime(2022, 1, 1))
        self.assertEqual(parse_date(datetime(2022, 1, 1)), datetime(2022, 1, 1))
        self.assertEqual(parse_date(date(2022, 1, 1)), date(2022, 1, 1))
        with self.assertRaises(CongressError):
            parse_date('invalid')

    def test_u(self):
        self.assertEqual(u(b'Hello, World!'), 'Hello, World!')
        self.assertEqual(u('Hello, World!'), 'Hello, World!')
        self.assertEqual(u(b'\r\nHello, World!'), 'Hello, World!')

    def test_get_offset(self):
        self.assertEqual(get_offset(1), 0)
        self.assertEqual(get_offset(2), 20)
        with self.assertRaises(CongressError):
            get_offset(0)

if __name__ == '__main__':
    unittest.main()
```

This code defines the `congress_utils` module with the specified functions and classes. It includes test cases to verify the correctness of each function using the `unittest` framework. The `check_chamber` function raises a `TypeError` if the input is invalid, and the `get_congress` function raises a `CongressError` if the year is before 1789. The `parse_date` function uses `dateutil.parser.parse` if available, otherwise falls back to `datetime.datetime.strptime`. The `u` function ensures that all input text is converted to Unicode, handling both binary and string types. The `get_offset` function raises a `CongressError` if the page number is less than 1. The `CURRENT_CONGRESS` constant holds the current Congress number based on the current year.

