    def test_get_contacts(self):
        response = self.client.get(reverse('contact-list'))
        self.assertEqual(response.status_code, status.HTTP_200_OK)

    def test_get_contacts_invalid(self):
        response = self.client.get(reverse('contact-list') + '?invalid=param')
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)

class TestContactDetail(APITestCase):
    def test_get_contact(self):
        contact = Contact.objects.create(name='John Doe', email='john@example.com', phone_number='1234567890')
        response = self.client.get(reverse('contact-detail', args=[contact.id]))
        self.assertEqual(response.status_code, status.HTTP_200_OK)

    def test_get_contact_invalid(self):
        response = self.client.get(reverse('contact-detail', args=[999]))
        self.assertEqual(response.status_code, status.HTTP_404_NOT_FOUND)

class TestContactCreate(APITestCase):
    def test_create_contact(self):
        data = {'name': 'Jane Doe', 'email': 'jane@example.com', 'phone_number': '9876543210'}
        response = self.client.post(reverse('contact-create'), data)
        self.assertEqual(response.status_code, status.HTTP_201_CREATED)

    def test_create_contact_invalid(self):
        data = {'name': 'Jane Doe', 'email': 'invalid_email', 'phone_number': '9876543210'}
        response = self.client.post(reverse('contact-create'), data)
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)

class TestContactUpdate(APITestCase):
    def test_update_contact(self):
        contact = Contact.objects.create(name='John Doe', email='john@example.com', phone_number='1234567890')
        data = {'name': 'Jane Doe', 'email': 'jane@example.com', 'phone_number': '9876543210'}
        response = self.client.put(reverse('contact-update', args=[contact.id]), data)
        self.assertEqual(response.status_code, status.HTTP_200_OK)

    def test_update_contact_invalid(self):
        contact = Contact.objects.create(name='John Doe', email='john@example.com', phone_number='1234567890')
        data = {'name': 'Jane Doe', 'email': 'invalid_email', 'phone_number': '9876543210'}
        response = self.client.put(reverse('contact-update', args=[contact.id]), data)
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)

class TestContactDelete(APITestCase):
    def test_delete_contact(self):
        contact = Contact.objects.create(name='John Doe', email='john@example.com', phone_number='1234567890')
        response = self.client.delete(reverse('contact-delete', args=[contact.id]))
        self.assertEqual(response.status_code, status.HTTP_204_NO_CONTENT)

    def test_delete_contact_invalid(self):
        response = self.client.delete(reverse('contact-delete', args=[999]))
        self.assertEqual(response.status_code, status.HTTP_404_NOT_FOUND)
