# Define the TestRegistry class
class TestRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, test_class):
        if not issubclass(test_class, Test):
            raise ValueError("Test class must inherit from Test")
        if test_class.name in self._registry:
            raise ValueError(f"Test class with name '{test_class.name}' already registered")
        self._registry[test_class.name] = test_class

    def get(self, name):
        if name not in self._registry:
            raise ValueError(f"Test class with name '{name}' not found")
        return self._registry[name]

    def list(self):
        return list(self._registry.keys())


# Test cases
class TestRegistryTest(unittest.TestCase):
    def setUp(self):
        self.registry = TestRegistry()

    def test_register(self):
        class MyTest(Test):
            def __init__(self):
