    samples = data['samples']
    if len(samples) == 1:
        sample = samples[0]
        mean = np.mean(sample)
        std = np.std(sample, ddof=1)
        z_score = (mean - 0) / (std / np.sqrt(len(sample)))
        return {'z_score': z_score, 'p_value': stats.norm.sf(abs(z_score)) * 2}
    elif len(samples) == 2:
        sample1 = samples[0]
        sample2 = samples[1]
        mean1 = np.mean(sample1)
        mean2 = np.mean(sample2)
        std1 = np.std(sample1, ddof=1)
