from flask import Flask, render_template
from flask_socketio import SocketIO, emit
from config import Config
from models import VoteStore

app = Flask(__name__)
app.config.from_object(Config)
socketio = SocketIO(app)

vote_store = VoteStore()

@socketio.on('submit vote')
def handle_vote(data):
    """Handle vote submission event"""
    try:
        vote = data['vote']
        if vote in ['yes', 'no', 'maybe']:
            vote_store.cast_vote(vote)
            emit('update totals', vote_store.get_totals(), broadcast=True)
        else:
            emit('error', 'Invalid vote selection')
    except Exception as e:
        emit('error', str(e))

@app.route('/')
def index():
    """Serve the index page"""
    return render_template('index.html', totals=vote_store.get_totals())

if __name__ == '__main__':
    socketio.run(app, host='0.0.0.0', port=5000)
```

