```python
import threading

class VoteStore:
    def __init__(self):
        self.votes = {'yes': 0, 'no': 0, 'maybe': 0}
        self.lock = threading.Lock()

    def cast_vote(self, vote):
        """Cast a vote and update the totals"""
        with self.lock:
            self.votes[vote] += 1

    def get_totals(self):
        """Get the current vote totals"""
        return self.votes
```

