        self.evidence_id = evidence_id
        self.archived = False

    def archive(self):
        self.archived = True

class ArchivingSystem:
    def __init__(self):
        self.audits = []
        self.assessments = []
        self.evidence = []

    def add_audit(self, audit):
        self.audits.append(audit)

    def add_assessment(self, assessment, audit):
