import click
from click.testing import CliRunner
import unittest

# Define a function to generate a title with an underline
def title(text, underline_char='-', to_title_case=True):
    if to_title_case:
        text = text.title()
    underline = underline_char * len(text)
    return f"{underline}\n{text}\n{underline}"

# Define a function to print text inside a box
def box(text, border_char='*'):
    lines = text.split('\n')
    max_length = max(len(line) for line in lines)
    box_lines = [border_char * (max_length + 2)]
    for line in lines:
        box_lines.append(f"{border_char} {line.ljust(max_length)} {border_char}")
    box_lines.append(border_char * (max_length + 2))
    return '\n'.join(box_lines)

# Define a function to simulate an evaluation process
class Evaluation:
    def __init__(self, success, failed_commands):
        self.success = success
        self.failed_commands = failed_commands

    def __str__(self):
        if self.success:
            return "Evaluation successful."
        else:
            return f"Failed commands: {', '.join(self.failed_commands)}"

# Define a function to print a summary of an evaluation
def summary(evaluation):
    if evaluation.success:
        click.echo("Evaluation successful.")
    else:
        click.echo(f"Failed commands: {', '.join(evaluation.failed_commands)}")

# Define the CLI commands
@click.group()
def cli():
    pass

@cli.command()
@click.argument('text')
@click.option('--underline_char', default='-', help='Character to use for the underline')
@click.option('--to_title_case', is_flag=True, help='Transform the text to title case')
def title_command(text, underline_char, to_title_case):
    """Print a title with an underline"""
    click.echo(title(text, underline_char, to_title_case))

@cli.command()
@click.argument('text')
@click.option('--border_char', default='*', help='Character to use for the box border')
def box_command(text, border_char):
    """Print text inside a box"""
    click.echo(box(text, border_char))

@cli.command()
@click.option('--verbose', is_flag=True, help='Print a detailed evaluation')
def evaluation_command(verbose):
    """Simulate an evaluation process"""
    evaluation = Evaluation(True, [])
    if verbose:
        click.echo(evaluation)
    else:
        click.echo("Evaluation successful.")

@cli.command()
@click.argument('evaluation', type=click.Path(exists=True))
def summary_command(evaluation):
    """Print a summary of an evaluation"""
    with open(evaluation, 'r') as f:
        evaluation_str = f.read()
    evaluation = Evaluation(eval(evaluation_str.split(':')[0]) == True, eval(evaluation_str.split(':')[1]))
    summary(evaluation)

# Run the CLI
if __name__ == '__main__':
    cli()

# Unit tests
class TestCLI(unittest.TestCase):
    def test_title_command(self):
        runner = CliRunner()
        result = runner.invoke(cli, ['title', 'Hello, World!', '--underline_char', '=', '--to_title_case'])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('Hello, World!', result.output)

    def test_box_command(self):
        runner = CliRunner()
        result = runner.invoke(cli, ['box', 'Hello, World!'])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('Hello, World!', result.output)

    def test_evaluation_command(self):
        runner = CliRunner()
        result = runner.invoke(cli, ['evaluation'])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('Evaluation successful.', result.output)

    def test_summary_command(self):
        runner = CliRunner()
        result = runner.invoke(cli, ['summary', 'True:[]'])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('Evaluation successful.', result.output)

if __name__ == '__main__':
    unittest.main()
```

