    def setUp(self):
        self.transformer = CellSeparatorsTransformer()

    def test_transform(self):
        input_lines = [
            CellSeparatorLine(),
            EmptyStringLine(),
            StringLine('print("Hello world")'),
            EmptyStringLine(),
            CellSeparatorLine(),
            EmptyStringLine(),
            StringLine('a = 5'),
