import importlib
import sys
import unittest

# Determine the Qt version being used
if sys.version_info.minor == 5:
    QT_API = 'PyQt5'
    QT_MODULE = 'PyQt5.Qt'
elif sys.version_info.minor == 6:
    QT_API = 'PySide6'
    QT_MODULE = 'PySide6.Qt'
else:
    raise ImportError('Unsupported Qt version')

# Import the necessary Qt modules dynamically
try:
    qt_module = importlib.import_module(QT_MODULE)
except ImportError as e:
    raise ImportError(f'Failed to import {QT_MODULE}: {e}')

# Define the QApplication class
class QApplication:
    def __init__(self, *args, **kwargs):
        self.app = qt_module.QApplication(*args, **kwargs)

    def exec(self):
        if QT_API == 'PyQt5':
            return self.app.exec_()
        else:
            return self.app.exec()

# Define the QAction and QShortcut classes
if QT_API == 'PySide6':
    class QAction(qt_module.QAction):
        pass

    class QShortcut(qt_module.QShortcut):
        pass

# Provide a way to determine the API name being used
def get_api_name():
    return QT_API

# Unit tests
class TestQtCompat(unittest.TestCase):
    def test_qapplication(self):
        app = QApplication()
        self.assertIsInstance(app.app, qt_module.QApplication)
        self.assertEqual(app.exec(), 0)

    def test_qaction(self):
        if QT_API == 'PySide6':
            action = QAction()
