        smart_home.add_switch("Test Switch")
        self.assertIn("Test Switch", smart_home.devices)

    def test_add_cover(self):
        smart_home = SmartHomeSystem()
        smart_home.add_cover("Test Cover")
        self.assertIn("Test Cover", smart_home.covers)

    def test_get_switch_state(self):
        smart_home = SmartHomeSystem()
        smart_home.add_switch("Test Switch")
        self.assertEqual(smart_home.get_switch_state("Test Switch"), "Switch Test Switch is OFF")

    def test_get_cover_state(self):
        smart_home = SmartHomeSystem()
        smart_home.add_cover("Test Cover")
        self.assertEqual(smart_home.get_cover_state("Test Cover"), "Cover Test Cover is CLOSED")

    def test_toggle_switch(self):
        smart_home = SmartHomeSystem()
        smart_home.add_switch("Test Switch")
        smart_home.toggle_switch("Test Switch")
        self.assertEqual(smart_home.get_switch_state("Test Switch"), "Switch Test Switch is ON")

    def test_turn_on_switch(self):
        smart_home = SmartHomeSystem()
        smart_home.add_switch("Test Switch")
        smart_home.turn_on_switch("Test Switch")
        self.assertEqual(smart_home.get_switch_state("Test Switch"), "Switch Test Switch is ON")

    def test_turn_off_switch(self):
        smart_home = SmartHomeSystem()
        smart_home.add_switch("Test Switch")
        smart_home.turn_on_switch("Test Switch")
        smart_home.turn_off_switch("Test Switch")
        self.assertEqual(smart_home.get_switch_state("Test Switch"), "Switch Test Switch is OFF")

