from django.http import JsonResponse
from django.views.decorators.http import require_http_methods
from django.core.exceptions import ValidationError
from AppCoder.models import Curso, Entregable
import json

@require_http_methods(["POST"])
def curso(request):
    try:
        data = json.loads(request.body)
        if 'nombre' not in data or 'camada' not in data:
            return JsonResponse({'error': 'Missing required fields'}, status=400)

        curso = Curso(
            nombre=data['nombre'],
            camada=data['camada']
        )
        curso.full_clean()
        curso.save()
        return JsonResponse({
            'message': 'Curso creado con éxito',
            'curso': {
                'id': curso.id,
                'nombre': curso.nombre,
                'camada': curso.camada
            }
        }, status=201)
    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON'}, status=400)
    except ValidationError as e:
        return JsonResponse({'error': str(e)}, status=400)

@require_http_methods(["POST"])
def entregables(request):
    try:
        data = json.loads(request.body)
        if 'nombre' not in data or 'fechaEntrega' not in data:
            return JsonResponse({'error': 'Missing required fields'}, status=400)

        entregable = Entregable(
            nombre=data['nombre'],
            fechaEntrega=data['fechaEntrega']
        )
        entregable.full_clean()
        entregable.save()
        return JsonResponse({
            'message': 'Entregable creado con éxito',
            'entregable': {
                'id': entregable.id,
                'nombre': entregable.nombre,
                'fechaEntrega': entregable.fechaEntrega
            }
        }, status=201)
    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON'}, status=400)
    except ValidationError as e:
        return JsonResponse({'error': str(e)}, status=400)
