Below is a high-level implementation of the user authentication and authorization system using Node.js, MongoDB, and Google OAuth2.

**Project Structure:**

```bash
auth-system/
app.js
config/
database.js
google-oauth2.js
jwt.js
models/
user.js
permission.js
routes/
auth.js
user.js
utils/
auth.js
logger.js
tests/
auth.test.js
user.test.js
package.json
```

**Dependencies:**

```bash
npm install express mongoose bcrypt jsonwebtoken google-auth-library
```

**Database Configuration (config/database.js):**

```javascript
const mongoose = require('mongoose');

mongoose.connect('mongodb://localhost/auth-system', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

const db = mongoose.connection;

db.on('error', (err) => {
  console.error(err);
});

db.once('open', () => {
  console.log('Connected to MongoDB');
});

module.exports = db;
```

**Google OAuth2 Configuration (config/google-oauth2.js):**

```javascript
const { google } = require('googleapis');

const clientId = 'YOUR_CLIENT_ID';
const clientSecret = 'YOUR_CLIENT_SECRET';
const redirectUri = 'YOUR_REDIRECT_URI';

const auth = new google.auth.OAuth2(clientId, clientSecret, redirectUri);

module.exports = auth;
```

**User Model (models/user.js):**

```javascript
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const userSchema = new mongoose.Schema({
  email: String,
  password: String,
  googleId: String,
  roles: [{ type: String }],
});

userSchema.pre('save', async function(next) {
  if (this.isModified('password')) {
    this.password = await bcrypt.hash(this.password, 10);
  }
  next();
});

module.exports = mongoose.model('User', userSchema);
```

**Permission Model (models/permission.js):**

```javascript
const mongoose = require('mongoose');

const permissionSchema = new mongoose.Schema({
  pvname: String,
  roles: [{ type: String }],
});

module.exports = mongoose.model('Permission', permissionSchema);
```

**Authentication Service (utils/auth.js):**

```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const User = require('../models/user');
const Permission = require('../models/permission');

const secretKey = 'YOUR_SECRET_KEY';

const authenticateLocal = async (email, password) => {
  const user = await User.findOne({ email });
  if (!user) {
    throw new Error('Invalid email or password');
  }
  const isValidPassword = await bcrypt.compare(password, user.password);
  if (!isValidPassword) {
    throw new Error('Invalid email or password');
  }
  const token = jwt.sign({ userId: user._id }, secretKey, {
    expiresIn: '1h',
  });
  return token;
};

const authenticateGoogle = async (googleId) => {
  const user = await User.findOne({ googleId });
  if (!user) {
    throw new Error('Invalid Google ID');
  }
  const token = jwt.sign({ userId: user._id }, secretKey, {
    expiresIn: '1h',
  });
  return token;
};

const authorize = async (token, pvname) => {
  const decoded = jwt.verify(token, secretKey);
  const user = await User.findById(decoded.userId);
  const permission = await Permission.findOne({ pvname });
  if (!permission) {
    throw new Error('Permission not found');
  }
  const hasRole = permission.roles.some((role) => user.roles.includes(role));
  if (!hasRole) {
    throw new Error('Unauthorized');
  }
  return true;
};

module.exports = { authenticateLocal, authenticateGoogle, authorize };
```

**Authorization Service (utils/auth.js):**

```javascript
const User = require('../models/user');
const Permission = require('../models/permission');

const getRoles = async (userId) => {
  const user = await User.findById(userId);
  return user.roles;
};

const hasRole = async (userId, pvname) => {
  const userRoles = await getRoles(userId);
  const permission = await Permission.findOne({ pvname });
  return permission.roles.some((role) => userRoles.includes(role));
};

module.exports = { getRoles, hasRole };
```

**Route for Local Authentication (routes/auth.js):**

```javascript
const express = require('express');
const router = express.Router();
const { authenticateLocal } = require('../utils/auth');

router.post('/local', async (req, res) => {
  try {
    const { email, password } = req.body;
    const token = await authenticateLocal(email, password);
    res.json({ token });
  } catch (error) {
    res.status(401).json({ error: 'Invalid email or password' });
  }
});

module.exports = router;
```

**Route for Google Authentication (routes/auth.js):**

```javascript
const express = require('express');
const router = express.Router();
const { authenticateGoogle } = require('../utils/auth');

router.get('/google', async (req, res) => {
  try {
    const { code } = req.query;
    const auth = require('../config/google-oauth2');
    const tokens = await auth.getToken(code);
    const token = await authenticateGoogle(tokens.tokens.id.access_token);
    res.json({ token });
  } catch (error) {
    res.status(401).json({ error: 'Invalid Google ID' });
  }
});

module.exports = router;
```

**Route for Authorization (routes/user.js):**

```javascript
const express = require('express');
const router = express.Router();
const { authorize } = require('../utils/auth');

router.get('/authorize', async (req, res) => {
  try {
    const { token, pvname } = req.query;
    const authorized = await authorize(token, pvname);
    res.json({ authorized });
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized' });
  }
});

module.exports = router;
```

**Unit Tests (tests/auth.test.js):**

```javascript
const { authenticateLocal, authenticateGoogle, authorize } = require('../utils/auth');
const User = require('../models/user');
const Permission = require('../models/permission');

describe('Authentication Service', () => {
  it('should authenticate local user', async () => {
    const user = new User({ email: 'test@example.com', password: 'password' });
    await user.save();
    const token = await authenticateLocal('test@example.com', 'password');
    expect(token).toBeInstanceOf(String);
  });

  it('should authenticate Google user', async () => {
    const user = new User({ googleId: 'google-id' });
    await user.save();
    const token = await authenticateGoogle('google-id');
    expect(token).toBeInstanceOf(String);
  });

  it('should authorize user', async () => {
    const user = new User({ _id: 'user-id', roles: ['admin'] });
    await user.save();
    const permission = new Permission({ pvname: 'pvname', roles: ['admin'] });
    await permission.save();
    const token = await authenticateLocal('test@example.com', 'password');
    const authorized = await authorize(token, 'pvname');
    expect(authorized).toBe(true);
  });
});
```

