from abc import ABC, abstractmethod
import os

# Define an abstract base class for scans
class Scan(ABC):
    @abstractmethod
    def execute(self, file_path):
        pass

# Define the BinaryScan class
class BinaryScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"BinaryScan executed for file: {file_name}"

# Define the FileScan class
class FileScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"FileScan executed for file: {file_name}"

# Define the JsonScan class
class JsonScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"JsonScan executed for file: {file_name}"

# Define the ArrowScan class
class ArrowScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"ArrowScan executed for file: {file_name}"

# Define the DocScan class
class DocScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"DocScan executed for file: {file_name}"

# Define the MaterializedScan class
class MaterializedScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"MaterializedScan executed for file: {file_name}"

# Define the PandasScan class
class PandasScan(Scan):
    def execute(self, file_path):
        file_name = os.path.basename(file_path)
        return f"PandasScan executed for file: {file_name}"

# Define the ScanManager class
class ScanManager:
    def __init__(self):
        self.scans = {}

    def register_scan(self, scan_type, file_extensions):
        if scan_type not in self.scans:
            self.scans[scan_type] = []
        for extension in file_extensions:
            self.scans[scan_type].append(extension)

    def execute_scan(self, file_path):
        file_extension = os.path.splitext(file_path)[1].lower()
        for scan_type, extensions in self.scans.items():
            if file_extension in extensions:
                scan = scan_type()
                return scan.execute(file_path)
        raise ValueError(f"Unsupported file extension: {file_extension}")

# Create a ScanManager instance and register scan types
scan_manager = ScanManager()
scan_manager.register_scan(BinaryScan, [".bin"])
scan_manager.register_scan(FileScan, [".txt"])
scan_manager.register_scan(JsonScan, [".json"])
scan_manager.register_scan(ArrowScan, [".arrow"])
scan_manager.register_scan(DocScan, [".docx", ".pdf"])
scan_manager.register_scan(MaterializedScan, [])
scan_manager.register_scan(PandasScan, [".csv"])

# Execute scans
print(scan_manager.execute_scan("example.bin"))
print(scan_manager.execute_scan("example.txt"))
print(scan_manager.execute_scan("example.json"))
print(scan_manager.execute_scan("example.arrow"))
print(scan_manager.execute_scan("example.docx"))
print(scan_manager.execute_scan("example.pdf"))
print(scan_manager.execute_scan("example.csv"))
try:
    print(scan_manager.execute_scan("example.mp3"))
except ValueError as e:
    print(e)
