```python
import unittest
from app import app, db
from forms import RegistrationForm, LoginForm, EditProfileForm, PostForm, ChangePasswordForm
from models import User, Post

class TestForms(unittest.TestCase):
    def setUp(self):
        app.config['TESTING'] = True
        app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
        db.create_all()

    def tearDown(self):
        db.session.remove()
        db.drop_all()

    def test_registration_form(self):
        form = RegistrationForm()
        self.assertTrue(form.validate())
        form.username.data = 'test'
        form.email.data = 'test@example.com'
        form.password.data = 'test'
        self.assertFalse(form.validate())

    def test_login_form(self):
        form = LoginForm()
        self.assertTrue(form.validate())
        form.username.data = 'test'
        form.password.data = 'test'
        self.assertFalse(form.validate())

    def test_edit_profile_form(self):
        form = EditProfileForm()
        self.assertTrue(form.validate())
        form.username.data = 'test'
        form.email.data = 'test@example.com'
        form.password.data = 'test'
        self.assertFalse(form.validate())

    def test_post_form(self):
        form = PostForm()
        self.assertTrue(form.validate())
        form.text.data = ''
        self.assertFalse(form.validate())

    def test_change_password_form(self):
        form = ChangePasswordForm()
        self.assertTrue(form.validate())
        form.current_password.data = 'test'
        form.new_password.data = 'test'
        self.assertFalse(form.validate())

if __name__ == '__main__':
    unittest.main()
