**GemSwap Match-3 Puzzle Game Implementation in Python**

### Game Design and Implementation

We will use object-oriented programming principles to design and implement the GemSwap game. The game will consist of the following classes:

*   `Gem`: Represents a single gem on the grid with its color and position.
*   `Grid`: Represents the 8x8 grid of gems, responsible for managing the gems and handling game logic.
*   `Game`: Represents the game itself, responsible for managing the grid, handling user input, and tracking the player's score.

### Code Implementation

```python
import random

class Gem:
    """Represents a single gem on the grid with its color and position."""
    def __init__(self, color, x, y):
        self.color = color
        self.x = x
        self.y = y

    def __repr__(self):
        return f"Gem({self.color}, {self.x}, {self.y})"


class Grid:
    """Represents the 8x8 grid of gems, responsible for managing the gems and handling game logic."""
    def __init__(self, width=8, height=8):
        self.width = width
        self.height = height
        self.gems = [[None for _ in range(width)] for _ in range(height)]
        self.generate_gems()

    def generate_gems(self):
        """Generate random gems for the grid."""
        colors = ['red', 'green', 'blue', 'yellow', 'purple', 'orange', 'pink', 'brown']
        for y in range(self.height):
            for x in range(self.width):
                self.gems[y][x] = Gem(random.choice(colors), x, y)

    def print_grid(self):
        """Print the current state of the grid."""
        for row in self.gems:
            print(' '.join(str(gem) if gem else '-' for gem in row))

    def swap_gems(self, x1, y1, x2, y2):
        """Swap two adjacent gems on the grid."""
        if self.gems[y1][x1] and self.gems[y2][x2]:
            self.gems[y1][x1], self.gems[y2][x2] = self.gems[y2][x2], self.gems[y1][x1]

    def check_matches(self):
        """Check for matches of three or more gems of the same color."""
        matches = []
        for y in range(self.height):
            for x in range(self.width):
                if self.gems[y][x]:
                    color = self.gems[y][x].color
                    count = 1
                    for dx in [-1, 0, 1]:
                        for dy in [-1, 0, 1]:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < self.width and 0 <= ny < self.height and self.gems[ny][nx] and self.gems[ny][nx].color == color:
                                count += 1
                                if count >= 3:
                                    matches.append((x, y, nx, ny))
        return matches

    def remove_matches(self, matches):
        """Remove matches from the grid."""
        for match in matches:
            x1, y1, x2, y2 = match
            self.gems[y1][x1] = None
            self.gems[y2][x2] = None

    def add_new_gems(self):
        """Add new gems to the grid to fill empty spaces."""
        for y in range(self.height):
            for x in range(self.width):
                if not self.gems[y][x]:
                    self.gems[y][x] = Gem(random.choice(['red', 'green', 'blue', 'yellow', 'purple', 'orange', 'pink', 'brown']), x, y)

    def is_game_over(self):
        """Check if no more moves are possible."""
        for y in range(self.height):
            for x in range(self.width):
                if self.gems[y][x]:
                    for dx in [-1, 0, 1]:
                        for dy in [-1, 0, 1]:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < self.width and 0 <= ny < self.height and self.gems[ny][nx]:
                                return False
        return True


class Game:
    """Represents the game itself, responsible for managing the grid, handling user input, and tracking the player's score."""
    def __init__(self):
        self.grid = Grid()
        self.score = 0

    def play(self):
        """Start the game."""
        while True:
            self.grid.print_grid()
            print(f"Score: {self.score}")
            x1 = int(input("Enter the x-coordinate of the first gem: ")) - 1
            y1 = int(input("Enter the y-coordinate of the first gem: ")) - 1
            x2 = int(input("Enter the x-coordinate of the second gem: ")) - 1
            y2 = int(input("Enter the y-coordinate of the second gem: ")) - 1
            self.grid.swap_gems(x1, y1, x2, y2)
            matches = self.grid.check_matches()
            if matches:
                self.grid.remove_matches(matches)
                self.score += len(matches)
                self.grid.add_new_gems()
            if self.grid.is_game_over():
                print("Game Over!")
                print(f"Final Score: {self.score}")
                break


if __name__ == "__main__":
    game = Game()
    game.play()
```

### Game Features

*   The game starts with a 8x8 grid of random gems.
*   The player can swap two adjacent gems by entering their coordinates.
*   When a match is made, the gems disappear, and the player's score increases.
*   New gems fall from the top to fill the empty spaces.
*   The game detects if no more moves are possible and ends with a final score.

