```python
class Branch(Node):
    def __init__(self, branch_id, parent=None):
        super().__init__()
        self.branch_id = branch_id
        self.parent = parent
        self.leaf = None

class Tree:
    def __init__(self):
        self.branches = {}

    def add_branch(self, branch):
        if branch.branch_id in self.branches:
            raise ValueError(f"Branch with ID {branch.branch_id} already exists.")
        self.branches[branch.branch_id] = branch

    def add_leaf(self, branch_id, leaf_value):
        if branch_id not in self.branches:
            raise ValueError(f"Branch with ID {branch_id} does not exist.")
        if leaf_value is None:
            raise ValueError("Leaf value cannot be None.")
        self.branches[branch_id].leaf = leaf_value

    def find_leaf(self, leaf_value):
        for branch in self.branches.values():
            if branch.leaf == leaf_value:
                return branch
        return None

import unittest

class TestTree(unittest.TestCase):
    def test_add_branch(self):
        tree = Tree()
        branch = Branch(1)
        tree.add_branch(branch)
        self.assertIn(1, tree.branches)

    def test_add_branch_duplicate(self):
        tree = Tree()
        branch = Branch(1)
        tree.add_branch(branch)
        with self.assertRaises(ValueError):
            tree.add_branch(branch)

    def test_add_leaf(self):
        tree = Tree()
        branch = Branch(1)
        tree.add_branch(branch)
        tree.add_leaf(1, "leaf_value")
        self.assertEqual(tree.branches[1].leaf, "leaf_value")

    def test_add_leaf_non_existent_branch(self):
        tree = Tree()
        with self.assertRaises(ValueError):
            tree.add_leaf(1, "leaf_value")

    def test_add_leaf_none_value(self):
        tree = Tree()
        branch = Branch(1)
        tree.add_branch(branch)
        with self.assertRaises(ValueError):
            tree.add_leaf(1, None)

    def test_find_leaf(self):
        tree = Tree()
        branch = Branch(1)
        tree.add_branch(branch)
        tree.add_leaf(1, "leaf_value")
        self.assertEqual(tree.find_leaf("leaf_value"), branch)

    def test_find_leaf_not_found(self):
        tree = Tree()
        branch = Branch(1)
        tree.add_branch(branch)
        self.assertIsNone(tree.find_leaf("non_existent_leaf"))

