def request_credit_limit():
    layout = [
        [sg.Text('Account Number:'), sg.Input(key='account_number')],
        [sg.Text('New Credit Limit:'), sg.Input(key='credit_limit')],
        [sg.Button('Request Credit Limit')]
    ]
    window = sg.Window('Request Credit Limit', layout)
    while True:
        event, values = window.read()
        if event == 'Request Credit Limit':
            account_number = values['account_number']
            credit_limit = values['credit_limit']
            if account_number in accounts and validate_initial_deposit(credit_limit):
                accounts[account_number]['credit_limit'] = float(credit_limit)
                sg.popup('Credit limit updated successfully!')
                break
            else:
                sg.popup('Invalid input!')
        elif event == sg.WINDOW_CLOSED:
            break
        window.close()

