```python
import os
import requests

def post_message_to_slack_channel(channel_id, message):
    """
    Posts a message to a specified Slack channel using the Slack API.

    Args:
        channel_id (str): The ID of the Slack channel to post the message to.
        message (str): The text of the message to be posted.

    Returns:
        dict: A dictionary containing the response from the Slack API, including a success status when the message is posted successfully.
    """

    # Validate the channel_id and message parameters
    if not isinstance(channel_id, str) or not channel_id:
        return {"error": "Channel ID must be a non-empty string"}
    if not isinstance(message, str) or not message:
        return {"error": "Message must be a non-empty string"}

    # Get the Slack bot token from the environment variable
    slack_bot_token = os.environ.get("SLACK_BOT_TOKEN")

    # Check if the Slack bot token is set
    if not slack_bot_token:
        return {"error": "Slack bot token is not set"}

    # Set the Slack API endpoint and headers
    slack_api_endpoint = "https://slack.com/api/chat.postMessage"
    headers = {"Authorization": f"Bearer {slack_bot_token}", "Content-Type": "application/json"}

    # Set the payload for the HTTP request
    payload = {"channel": channel_id, "text": message}

    try:
        # Send the HTTP request to the Slack API
        response = requests.post(slack_api_endpoint, headers=headers, json=payload)

        # Check if the HTTP request was successful
        if response.status_code == 200:
            # Return a dictionary containing the response from the Slack API
            return {"success": True, "response": response.json()}
        else:
            # Return a dictionary containing an error message
            return {"error": f"Failed to post message to Slack channel. Status code: {response.status_code}"}
    except requests.exceptions.RequestException as e:
        # Return a dictionary containing an error message if an exception occurs
        return {"error": f"An error occurred while posting message to Slack channel: {str(e)}"}

# Example usage:
print(post_message_to_slack_channel("C012345678", "Hello, world!"))
```

