import requests
from TCPclient import TCPclient  # Assuming TCPclient is a custom class for simulating user input and output

class WikipediaAssistant:
    def __init__(self):
        self.tcp_client = TCPclient()

    def isValid(self, text):
        """Check if the input text contains the trigger word "Wikipedia"."""
        return "Wikipedia" in text

    def handle(self, text):
        """Fetch Wikipedia summary and output the first three sentences."""
        if self.isValid(text):
            self.tcp_client.send("Please enter a search term: ")
            search_term = self.tcp_client.recv()
            if search_term == "Wikipedia":
                self.tcp_client.send("Please enter a different search term: ")
                search_term = self.tcp_client.recv()
            try:
                url = f"https://en.wikipedia.org/w/api.php?action=parse&page={search_term}&format=json"
                response = requests.get(url)
                data = response.json()
                summary = data["parse"]["text"]["*"]
                sentences = summary.split(". ")
                if len(sentences) > 3:
                    output = ". ".join(sentences[:3]) + "."
                else:
                    output = ". ".join(sentences) + "."
                self.tcp_client.send(output)
            except Exception as e:
                self.tcp_client.send(f"An error occurred: {str(e)}")
        else:
            self.tcp_client.send("Please say 'Wikipedia' to start the search.")

def main():
    assistant = WikipediaAssistant()
    while True:
        text = input("Simulated user input: ")
        assistant.handle(text)

if __name__ == "__main__":
    main()
