import csv
import webbrowser
import random

def load_iching_dict(filename):
    """Loads the I Ching dictionary from a CSV file."""
    try:
        with open(filename, 'r') as file:
            reader = csv.DictReader(file)
            iching_dict = {row['binary_representation']: row for row in reader}
            return iching_dict
    except FileNotFoundError:
        print(f"Error: The file '{filename}' was not found.")
        return None
    except Exception as e:
        print(f"Error: Unable to read the file '{filename}'. {str(e)}")
        return None

def cast_coins():
    """Simulates the casting of three coins six times to create a hexagram."""
    return [random.choice([2, 3]) for _ in range(6)]

def get_hexagram_details(iching_dict, binary_representation):
    """Gets the details of a hexagram from the I Ching dictionary."""
    return iching_dict.get(binary_representation, {'hexagram_number': 'Unknown', 'hexagram_name': 'Unknown', 'hexagram_description': 'Unknown'})

def main():
    iching_dict = load_iching_dict('ichingdict.csv')
    if iching_dict is None:
        return

    for _ in range(6):
        coins = cast_coins()
        binary_representation = ''.join(map(str, coins))
        hexagram_details = get_hexagram_details(iching_dict, binary_representation)
        print(f"Hexagram Number: {hexagram_details['hexagram_number']}")
        print(f"Hexagram Name: {hexagram_details['hexagram_name']}")
        print(f"Hexagram Description: {hexagram_details['hexagram_description']}\n")

        while True:
            user_input = input("Would you like to open a webpage with more information about the drawn hexagram? (y/n): ")
            if user_input.lower() == 'y':
                url = f"https://en.wikipedia.org/wiki/{hexagram_details['hexagram_name'].replace('\'', '').replace(' ', '_')}"
                webbrowser.open(url)
                break
            elif user_input.lower() == 'n':
                return
            else:
                print("Error: Invalid input. Please enter 'y' or 'n'.")

if __name__ == "__main__":
    main()
```

