### Game Description

Quixo is a 2-player strategy board game where players take turns sliding pieces on a 5x5 board to form a line of their own tokens. The game is won by the player who forms a line of their tokens.

### Code

```python
import random

class QuixoBoard:
    def __init__(self):
        self.board = [[i + j * 5 for i in range(1, 6)] for j in range(5)]
        self.player_turn = 'O'

    def display_board(self):
        print('\n' + '-' * 25)
        for row in self.board:
            print(' | '.join(str(cell) for cell in row))
            print('-' * 25)
        print()

    def is_valid_move(self, piece, target):
        if piece < 1 or piece > 25 or target < 1 or target > 25:
            return False
        if self.board[(target - 1) // 5][(target - 1) % 5] != piece:
            return False
        if abs((target - 1) // 5 - (piece - 1) // 5) > 1 or abs((target - 1) % 5 - (piece - 1) % 5) > 1:
            return False
        return True

    def make_move(self, piece, target):
        if not self.is_valid_move(piece, target):
            raise ValueError("Invalid move")
        self.board[(target - 1) // 5][(target - 1) % 5] = self.board[(piece - 1) // 5][(piece - 1) % 5]
        self.board[(piece - 1) // 5][(piece - 1) % 5] = 0
        self.player_turn = 'X' if self.player_turn == 'O' else 'O'

    def check_win(self):
        for i in range(5):
            if self.board[i][0] != 0 and all(cell == self.board[i][0] for cell in self.board[i]):
                return self.board[i][0]
            if self.board[0][i] != 0 and all(cell == self.board[0][i] for cell in [row[i] for row in self.board]):
                return self.board[0][i]
        if self.board[0][0] != 0 and all(cell == self.board[0][0] for cell in [self.board[i][i] for i in range(5)]):
            return self.board[0][0]
        if self.board[0][4] != 0 and all(cell == self.board[0][4] for cell in [self.board[i][4 - i] for i in range(5)]):
            return self.board[0][4]
        return None

class AlphaBetaAI:
    def __init__(self, board):
        self.board = board

    def alpha_beta(self, depth, alpha, beta, maximizing_player):
        if depth == 0 or self.board.check_win():
            return self.evaluate_board()
        if maximizing_player:
            value = -float('inf')
            for i in range(1, 26):
                if self.board.board[(i - 1) // 5][(i - 1) % 5] == 0:
                    self.board.make_move(i, i + 5)
                    value = max(value, self.alpha_beta(depth - 1, alpha, beta, False))
                    self.board.make_move(i, i - 5)
                    alpha = max(alpha, value)
                    if alpha >= beta:
                        break
            return value
        else:
            value = float('inf')
            for i in range(1, 26):
                if self.board.board[(i - 1) // 5][(i - 1) % 5] == 0:
                    self.board.make_move(i, i + 5)
                    value = min(value, self.alpha_beta(depth - 1, alpha, beta, True))
                    self.board.make_move(i, i - 5)
                    beta = min(beta, value)
                    if alpha >= beta:
                        break
            return value

    def evaluate_board(self):
        win = self.board.check_win()
        if win == 'O':
            return 1
        elif win == 'X':
            return -1
        else:
            return 0

def main():
    board = QuixoBoard()
    ai = AlphaBetaAI(board)
    while True:
        board.display_board()
        if board.player_turn == 'O':
            piece = int(input("Enter the piece to move (1-25): "))
            target = int(input("Enter the target position (1-25): "))
            try:
                board.make_move(piece, target)
            except ValueError as e:
                print(e)
                continue
        else:
            best_move = None
            best_value = -float('inf')
            for i in range(1, 26):
                if board.board[(i - 1) // 5][(i - 1) % 5] == 0:
                    board.make_move(i, i + 5)
                    value = ai.alpha_beta(5, -float('inf'), float('inf'), False)
                    board.make_move(i, i - 5)
                    if value > best_value:
                        best_value = value
                        best_move = i
            board.make_move(best_move, best_move + 5)
        win = board.check_win()
        if win is not None:
            board.display_board()
            print(f"Player {win} wins!")
            break

if __name__ == "__main__":
    main()
```

### Explanation

The code consists of two main classes: `QuixoBoard` and `AlphaBetaAI`. The `QuixoBoard` class represents the game board and handles moves, checking for wins, and displaying the board. The `AlphaBetaAI` class implements the Alpha-Beta pruning algorithm to determine the best move for the AI player.

In the `main` function, the game loop continues until a player wins. The AI player makes a move by calling the `alpha_beta` method, which recursively explores the game tree and returns the best move. The human player inputs their move by specifying the piece to move and the target position.

