```python
import base64
import datetime
import decimal
import hashlib
import os
import unittest

# Define a simple encryption and decryption function
def encrypt(value, key):
    return base64.b64encode(hashlib.sha256((value + key).encode()).digest())

def decrypt(encrypted_value, key):
    return base64.b64decode(encrypted_value).decode()

class Secure:
    def __init__(self, value, key, access_level):
        self.key = key
        self.access_level = access_level
        if not isinstance(value, str):
            raise ValueError("Value must be a string")
        self.encrypted_value = encrypt(value, key)
        self.value = self.decrypt_value()

    def decrypt_value(self):
        if self.access_level == "admin":
            return decrypt(self.encrypted_value, self.key)
        else:
            raise PermissionError("Access denied")

    def get_value(self):
        return self.decrypt_value()

    def get_typed_value(self):
        return self.get_value()

class SecureString(Secure, str):
    def __init__(self, value, key, access_level):
        super().__init__(value, key, access_level)

class SecureDecimal(Secure, decimal.Decimal):
    def __init__(self, value, key, access_level):
        super().__init__(str(value), key, access_level)

    def get_typed_value(self):
        return decimal.Decimal(self.get_value())

class SecureDate(Secure, datetime.date):
    def __init__(self, value, key, access_level):
        super().__init__(str(value), key, access_level)

    def get_typed_value(self):
        return datetime.date.fromisoformat(self.get_value())

class SecureDateTime(Secure, datetime.datetime):
    def __init__(self, value, key, access_level):
        super().__init__(str(value), key, access_level)

    def get_typed_value(self):
        return datetime.datetime.fromisoformat(self.get_value())

class SecureIncompleteDate(Secure, datetime.date):
    def __init__(self, value, key, access_level):
        super().__init__(str(value), key, access_level)

    def get_typed_value(self):
        return datetime.date.fromisoformat(self.get_value())

class TestSecure(unittest.TestCase):
    def test_secure_string(self):
        key = os.urandom(32)
        access_level = "admin"
        secure_string = SecureString("Hello, World!", key, access_level)
        self.assertEqual(secure_string.get_typed_value(), "Hello, World!")
        self.assertEqual(secure_string.get_value(), "Hello, World!")

    def test_secure_decimal(self):
        key = os.urandom(32)
        access_level = "admin"
        secure_decimal = SecureDecimal(123.45, key, access_level)
        self.assertEqual(secure_decimal.get_typed_value(), decimal.Decimal('123.45'))
        self.assertEqual(secure_decimal.get_value(), "123.45")

    def test_secure_date(self):
        key = os.urandom(32)
        access_level = "admin"
        secure_date = SecureDate(datetime.date(2022, 1, 1), key, access_level)
        self.assertEqual(secure_date.get_typed_value(), datetime.date(2022, 1, 1))
        self.assertEqual(secure_date.get_value(), "2022-01-01")

    def test_secure_datetime(self):
        key = os.urandom(32)
        access_level = "admin"
        secure_datetime = SecureDateTime(datetime.datetime(2022, 1, 1, 12, 0, 0), key, access_level)
        self.assertEqual(secure_datetime.get_typed_value(), datetime.datetime(2022, 1, 1, 12, 0))
        self.assertEqual(secure_datetime.get_value(), "2022-01-01 12:00:00")

    def test_secure_incomplete_date(self):
        key = os.urandom(32)
        access_level = "admin"
        secure_incomplete_date = SecureIncompleteDate(datetime.date(2022, 1, 1), key, access_level)
        self.assertEqual(secure_incomplete_date.get_typed_value(), datetime.date(2022, 1, 1))
        self.assertEqual(secure_incomplete_date.get_value(), "2022-01-01")

    def test_access_denied(self):
        key = os.urandom(32)
        access_level = "user"
        secure_string = SecureString("Hello, World!", key, access_level)
        with self.assertRaises(PermissionError):
            secure_string.get_value()

    def test_invalid_data_type(self):
        key = os.urandom(32)
        access_level = "admin"
        with self.assertRaises(ValueError):
            Secure(123, key, access_level)

if __name__ == "__main__":
    unittest.main()
```

