    """
    default_validators = [
        RegexValidator(
            r'^\+?\d{1,3}\s?\(?\d{1,3}\)?[\s.-]?\d{1,3}[\s.-]?\d{1,4}$',
            _('Phone number must be in international format (e.g. +1 1234567890)'),
            'invalid_phone_number'
        ),
    ]

    def __init__(self, *args, **kwargs):
        super().__init__(*args, max_length=30, **kwargs)

    def deconstruct(self):
        name, path, args, kwargs = super().deconstruct()
        del kwargs['max_length']
        return name, path, args, kwargs

    def formfield(self, **kwargs):
        from django.forms import CharField
        kwargs.setdefault('widget', CharField.widget)
        return super().formfield(**kwargs)

    def to_python(self, value):
        if value in self.empty_values:
            return None
        return value

    def get_prep_value(self, value):
        if value is None:
            return None
        return value

    def value_to_string(self, obj):
        return self.value_from_object(obj)

    def value_from_object(self, obj):
        value = self.get_prep_value(obj)
        if value is None:
            return ''
        return value

    def formfield_callback(self, **kwargs):
        from django.forms import CharField
        kwargs.setdefault('widget', CharField.widget)
        return super().formfield(**kwargs)


class Contact(models.Model):
    """
    Model to store contact information.
    """
    phone_number = PhoneField(_('Phone number in international format'), blank=False, null=False)

    class Meta:
        verbose_name = _('Contact')
        verbose_name_plural = _('Contacts')

    def __str__(self):
        return f'Contact {self.id}'

    def clean(self):
        if not self.phone_number:
            raise ValueError(_('Phone number cannot be empty'))
